package net.officefloor.hq.app.audit;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/** The audit viewer: the sheet's lines exactly as the audit file holds them, newest first,
 *  optionally only those about one person. For a person, this sheet's lines about them are
 *  followed by each of its descendants' lines about them (sheets by id, each newest first), then,
 *  for a person transferred here, by the sheet they came from's lines about them, up to their
 *  transfer, newest first. It reads the file; it records nothing. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/audit")
@Validated
public class AuditController {

    /** A field of a record: its key, then its value up to the next field (a value may hold spaces). */
    private static final Pattern FIELD = Pattern.compile("(?<= )([A-Za-z][\\w-]*)=(.*?)(?= [A-Za-z][\\w-]*=|$)");

    private final Audit audit;
    private final PersonRepository people;
    private final SheetRepository sheets;

    public AuditController(Audit audit, PersonRepository people, SheetRepository sheets) {
        this.audit = audit;
        this.people = people;
        this.sheets = sheets;
    }

    @GetMapping
    public List<String> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestParam(required = false) @Size(max = 200) String name) {
        String sheet = sheetId.trim();
        String person = name == null || name.isBlank() ? null : key(name);
        List<String> lines = audit.lines();
        List<String> shown = about(lines, sheet, person);
        if (person != null) {
            sheets.descendants(sheet).stream().sorted()
                    .forEach(descendant -> shown.addAll(about(lines, descendant, person)));
            String origin = people.findBySheetIdAndNameIgnoreCase(sheet, name.trim()).map(Person::getOrigin)
                    .orElse(null);
            if (origin != null) {
                shown.addAll(untilTransfer(about(lines, origin, person), sheet));
            }
        }
        return shown;
    }

    /** The sheet's lines (about the person, when one is given), newest first. */
    private static List<String> about(List<String> lines, String sheet, String person) {
        List<String> shown = new ArrayList<>();
        for (String line : lines) {
            if (matches(line, sheet, person)) {
                shown.add(line);
            }
        }
        Collections.reverse(shown);
        return shown;
    }

    /** The lines (newest first) from the latest transfer to the sheet given on; all of them when
     *  there is none. */
    private static List<String> untilTransfer(List<String> newestFirst, String toSheet) {
        for (int i = 0; i < newestFirst.size(); i++) {
            String line = newestFirst.get(i);
            if (line.startsWith("PERSON_TRANSFERRED ") && toSheet.equals(field(line, "to"))) {
                return newestFirst.subList(i, newestFirst.size());
            }
        }
        return newestFirst;
    }

    /** The value of the line's field, or null when it has none. */
    private static String field(String line, String key) {
        Matcher m = FIELD.matcher(line);
        while (m.find()) {
            if (m.group(1).equals(key)) {
                return m.group(2);
            }
        }
        return null;
    }

    /** Whether the line is of the sheet and, when a person is asked for, carries name= or person= of them. */
    private static boolean matches(String line, String sheet, String person) {
        boolean ofSheet = false;
        boolean aboutPerson = person == null;
        Matcher m = FIELD.matcher(line);
        while (m.find()) {
            String field = m.group(1);
            String value = m.group(2);
            if (field.equals("sheet") && value.equals(sheet)) {
                ofSheet = true;
            } else if (person != null && (field.equals("name") || field.equals("person")) && key(value).equals(person)) {
                aboutPerson = true;
            }
        }
        return ofSheet && aboutPerson;
    }

    /** A name as names are compared: case and surrounding spaces ignored. */
    private static String key(String name) {
        return name.trim().toLowerCase(Locale.ROOT);
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.List;
import java.util.Set;
import java.util.function.Supplier;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.web.context.request.RequestAttributes;
import org.springframework.web.context.request.RequestContextHolder;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The request attribute holding a {@code Supplier<String>} of the steward the requesting user
     *  acts for by delegation (null when none, as of the sheet's today when asked): each record of
     *  the change, but those that only report figures, then ends with {@code for=<steward>}. */
    public static final String ACTING_FOR = Audit.class.getName() + ".actingFor";

    /** The records that only report figures, never marked with who a change was made for. */
    private static final Set<String> FIGURES_ONLY = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing. Outside a transaction the record is appended at once.
     */
    public void recordOnCommit(String line) {
        String entry = withActingFor(line);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** The record ending with who the change was made for, when the requesting user acts for a
     *  steward by delegation and the record is not one that only reports figures. */
    private static String withActingFor(String entry) {
        RequestAttributes request = RequestContextHolder.getRequestAttributes();
        if (request == null || FIGURES_ONLY.contains(entry.split(" ", 2)[0])) {
            return entry;
        }
        if (request.getAttribute(ACTING_FOR, RequestAttributes.SCOPE_REQUEST) instanceof Supplier<?> actingFor
                && actingFor.get() instanceof String steward) {
            return entry + " for=" + steward;
        }
        return entry;
    }

    /** Every record the file holds now, oldest first (none when there is no file yet). */
    public synchronized List<String> lines() {
        try {
            return Files.exists(file)
                    ? Files.readAllLines(file, StandardCharsets.UTF_8).stream().filter(l -> !l.isEmpty()).toList()
                    : List.of();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
